def response_optimal(prob, epoch, x, y, q, mlu, migration, loads):
    flows = []
    idx = 0
    for paths in prob.paths:
        row = []
        for _ in paths:
            row.append(_num(x[idx]))
            idx += 1
        flows.append(row)
    return {
        "epoch": epoch,
        "status": "optimal",
        "flows": flows,
        "loads": [_num(v) for v in loads],
        "mlu": _num(mlu),
        "migration": _num(migration),
        "dual": {
            "inequality": [_num(v) for v in y],
            "equality": [_num(v) for v in q],
        },
    }


def response_infeasible(epoch, y, q):
    return {
        "epoch": epoch,
        "status": "infeasible",
        "certificate": {
            "inequality": [_num(v) for v in y],
            "equality": [_num(v) for v in q],
        },
    }


def _pick_duals(prob, pairs, target):
    """Choose the best dual pair for an optimal response."""
    best = None
    best_key = None
    for y, q in pairs:
        if y is None or q is None:
            continue
        col, ymax, dl = dual_quality(prob, y, q, target)
        if not np.isfinite(col):
            continue
        mag = float(np.max(np.abs(np.concatenate([y, q])))) \
            if (y.size + q.size) else 0.0
        ok = col <= COL_TOL and ymax <= COL_TOL and dl <= 1e-7 and mag <= 1e8
        key = (0, mag) if ok else (1, max(col, ymax, dl * 1e-2))
        if best_key is None or key < best_key:
            best_key = key
            best = (y, q)
    if best is None:
        # keep whatever HiGHS produced rather than emitting nothing
        for y, q in pairs:
            if y is not None and q is not None:
                return y, q
        return np.zeros(prob.R), np.zeros(prob.K)
    return best[0], best[1]


def handle(req):
    _DEADLINE[0] = time.time() + RESPONSE_BUDGET
    prob = Problem(req)
    state, x, y, q, resid = solve_primal(prob)
    if state in ("optimal", "weak"):
        xc, t, loads, mlu, migration = primal_from_flows(prob, x)
        y, q = _pick_duals(prob, [(y, q), solve_dual_lp(prob)], mlu)
        if state == "optimal":
            return response_optimal(prob, req["epoch"], xc, y, q, mlu,
                                    migration, loads)
    if state == "infeasible":
        fy, fq, _ok = solve_infeasible(prob)
        if fy is not None:
            return response_infeasible(req["epoch"], fy, fq)
        sys.stderr.write("infeasible without witness\n")
        return {"status": "invalid"}
    if state == "unknown":
        fy, fq, ok = solve_infeasible(prob)
        if ok:
            return response_infeasible(req["epoch"], fy, fq)
        sys.stderr.write("unsolved request\n")
        return {"status": "invalid"}
    # doubtful primal: only trust a witness that passes the tight gate
    if state == "weak":
        if resid <= 5e-6:
            xc, t, loads, mlu, migration = primal_from_flows(prob, x)
            return response_optimal(prob, req["epoch"], xc, y, q, mlu,
                                    migration, loads)
        fy, fq, ok = solve_infeasible(prob)
        if ok:
            return response_infeasible(req["epoch"], fy, fq)
        xc, t, loads, mlu, migration = primal_from_flows(prob, x)
        return response_optimal(prob, req["epoch"], xc, y, q, mlu,
                                migration, loads)
    sys.stderr.write("unreachable state %s\n" % (state,))
    return {"status": "invalid"}


